ray_source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    blank_columns = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3:
                if grid[r][c] == 0:
                    blank_columns.add(c)
                elif grid[r][c] != 3:
                    centers.append((r, c, grid[r][c]))

    def ray(r, c, dr, dc, color, own):
        nr, nc = r + dr, c + dc
        while 0 <= nr < h and 0 <= nc < w:
            if grid[nr][nc] == 3:
                # The marker's own four arms are transparent to its rays;
                # any other 3 stops the ray.
                if (nr, nc) != own:
                    break
            elif not (dc != 0 and nc in blank_columns):
                out[nr][nc] = color
            nr += dr
            nc += dc

    for r, c, color in centers:
        ray(r, c, 0, -1, color, (r, c-1))
        ray(r, c, 0, 1, color, (r, c+1))
    for r, c, color in centers:
        ray(r, c, -1, 0, color, (r-1, c))
        ray(r, c, 1, 0, color, (r+1, c))
    return out
'''
