def crossgrid(h,w,markers,blanks=()):
    g=[[0]*w for _ in range(h)]
    for r,c,col in markers:
        g[r][c]=col
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)): g[r+dr][c+dc]=3
    for r,c in blanks:
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)): g[r+dr][c+dc]=3
    return g
